/**
 * Theme presets.
 *
 * A theme is three sRGB channel triplets and nothing else. Everything the
 * interface does with colour — the accent ramp, the ambient washes, the
 * card sheen, the orb's glow, the focus ring, the selection colour — is
 * derived from those three values at runtime by `rgb(var(--accent-rgb) /
 * <alpha>)` in the stylesheet. That is why adding a theme here costs five
 * lines instead of an audit of every component.
 *
 * The palettes are hand-tuned rather than generated by rotating a hue.
 * A dark UI is unforgiving: an accent needs luminance above roughly 180
 * to read as light rather than as paint, and its hue has to survive being
 * rendered at 8% alpha over #07070a without going muddy. Automatic hue
 * rotation fails both tests, so these are picked by eye.
 */

export interface ThemePreset {
  id: string;
  label: string;
  /** One line describing the mood, shown under the swatch. */
  mood: string;
  /** Primary accent, as `R G B`. */
  accent: string;
  /** Secondary accent, used for `acting`, the horizon wash, and memory. */
  accent2: string;
}

